package eu.kanade.tachiyomi.extension.tr.mangtto

import eu.kanade.tachiyomi.network.GET
import eu.kanade.tachiyomi.source.model.FilterList
import eu.kanade.tachiyomi.source.model.MangasPage
import eu.kanade.tachiyomi.source.model.Page
import eu.kanade.tachiyomi.source.model.SChapter
import eu.kanade.tachiyomi.source.model.SManga
import eu.kanade.tachiyomi.source.online.HttpSource
import kotlinx.serialization.decodeFromString
import kotlinx.serialization.json.Json
import okhttp3.Headers
import okhttp3.OkHttpClient
import okhttp3.Request
import okhttp3.Response
import java.util.concurrent.TimeUnit

class Mangtto : HttpSource() {

    override val name = "Mangtto"
    override val baseUrl = "https://mangtto.com"
    override val lang = "tr"
    override val supportsLatest = true

    private val json = Json {
        ignoreUnknownKeys = true
        isLenient = true
        coerceInputValues = true
    }

    override val client: OkHttpClient = network.cloudflareClient.newBuilder()
        .connectTimeout(15, TimeUnit.SECONDS)
        .readTimeout(30, TimeUnit.SECONDS)
        .build()

    override fun headersBuilder(): Headers.Builder = super.headersBuilder()
        .add("Referer", "$baseUrl/")
        .add("Origin", baseUrl)

    // Popular
    override fun popularMangaRequest(page: Int): Request {
        val skip = (page - 1) * 24
        return GET("$baseUrl/api/manga/populer?skip=$skip&take=24", headers)
    }

    override fun popularMangaParse(response: Response): MangasPage {
        val data = json.decodeFromString<MangttoPopularData>(response.body.string())
        val mangas = data.mangas.map { it.toSManga() }
        val hasNextPage = mangas.size >= 24
        return MangasPage(mangas, hasNextPage)
    }

    // Latest
    override fun latestUpdatesRequest(page: Int): Request {
        val skip = (page - 1) * 24
        return GET("$baseUrl/api/manga/latest?skip=$skip&take=24", headers)
    }

    override fun latestUpdatesParse(response: Response): MangasPage {
        val data = json.decodeFromString<MangttoLatestData>(response.body.string())
        val mangas = data.chapters
            .mapNotNull { it.manga }
            .distinctBy { it.slug }
            .map { it.toSManga() }
        val hasNextPage = data.chapters.size >= 24
        return MangasPage(mangas, hasNextPage)
    }

    // Search
    override fun searchMangaRequest(page: Int, query: String, filters: FilterList): Request {
        return GET("$baseUrl/api/manga/search?page=$page&q=$query", headers)
    }

    override fun searchMangaParse(response: Response): MangasPage {
        val data = json.decodeFromString<MangttoSearchData>(response.body.string())
        val mangas = data.hits.map { it.document.toSManga() }
        val hasNextPage = mangas.size >= 24
        return MangasPage(mangas, hasNextPage)
    }

    // Details
    override fun mangaDetailsRequest(manga: SManga): Request {
        return GET("$baseUrl/api/manga/${manga.url}", headers)
    }

    override fun mangaDetailsParse(response: Response): SManga {
        val data = json.decodeFromString<MangttoDetailData>(response.body.string())
        return data.toSManga()
    }

    // Chapters
    override fun chapterListRequest(manga: SManga): Request {
        return GET("$baseUrl/api/manga/${manga.url}/chapters?skip=0&take=1000", headers)
    }

    override fun chapterListParse(response: Response): List<SChapter> {
        val segments = response.request.url.pathSegments
        val mangaSlug = segments.getOrNull(segments.size - 2) ?: ""
        val data = json.decodeFromString<MangttoChapterPageData>(response.body.string())

        return data.chapters
            .map { it.toSChapter(mangaSlug) }
            .sortedByDescending { it.chapter_number }
    }

    // Pages
    override fun pageListRequest(chapter: SChapter): Request {
        return GET("$baseUrl/api/manga/${chapter.url}", headers)
    }

    override fun pageListParse(response: Response): List<Page> {
        val segments = response.request.url.pathSegments
        val slug = segments.getOrNull(segments.size - 2) ?: ""
        val chNum = segments.lastOrNull() ?: ""
        val data = json.decodeFromString<MangttoPageData>(response.body.string())
        val upload = data.uploads.firstOrNull() ?: return emptyList()
        val fansubId = upload.fansubId ?: ""

        return (1..upload.fileLength).map { i ->
            val imgUrl = "${data.cdn}/manga/$slug/$chNum/$i-$fansubId.webp"
            Page(i - 1, "", imgUrl)
        }
    }

    override fun imageUrlParse(response: Response): String = throw UnsupportedOperationException()
}

package eu.kanade.tachiyomi.extension.tr.mangtto

import eu.kanade.tachiyomi.source.model.SChapter
import eu.kanade.tachiyomi.source.model.SManga
import kotlinx.serialization.Serializable

@Serializable
class MangttoPopularData(
    val mangas: List<MangttoManga> = emptyList(),
    val total: Int = 0,
)

@Serializable
class MangttoLatestData(
    val chapters: List<MangttoLatestChapter> = emptyList(),
    val total: Int = 0,
)

@Serializable
class MangttoLatestChapter(
    val chapter: Float? = null,
    val manga: MangttoManga? = null,
)

@Serializable
class MangttoSearchData(
    val hits: List<MangttoSearchHit> = emptyList(),
    val estimatedTotalHits: Int = 0,
)

@Serializable
class MangttoSearchHit(
    val document: MangttoManga,
)

@Serializable
class MangttoManga(
    val title: String = "",
    val slug: String = "",
    val coverImage: String? = null,
) {
    fun toSManga(): SManga = SManga.create().apply {
        this.title = this@MangttoManga.title
        this.url = this@MangttoManga.slug
        this.thumbnail_url = this@MangttoManga.coverImage
    }
}

@Serializable
class MangttoDetailData(
    val slug: String = "",
    val title: String = "",
    val status: String? = null,
    val description: String? = null,
    val coverImage: String? = null,
    val genres: List<MangttoGenre> = emptyList(),
) {
    fun toSManga(): SManga = SManga.create().apply {
        this.title = this@MangttoDetailData.title
        this.url = this@MangttoDetailData.slug
        this.thumbnail_url = this@MangttoDetailData.coverImage
        this.description = this@MangttoDetailData.description
        this.status = when (this@MangttoDetailData.status) {
            "FINISHED" -> SManga.COMPLETED
            "RELEASING" -> SManga.ONGOING
            "HIATUS" -> SManga.ON_HIATUS
            "CANCELLED" -> SManga.CANCELLED
            else -> SManga.UNKNOWN
        }
        this.genre = this@MangttoDetailData.genres.joinToString { it.name }
        this.initialized = true
    }
}

@Serializable
class MangttoGenre(val name: String = "")

@Serializable
class MangttoChapterPageData(
    val chapters: List<MangttoChapter> = emptyList(),
    val total: Int = 0,
)

@Serializable
class MangttoChapter(
    val id: String? = null,
    val chapter: Float = 0f,
) {
    fun toSChapter(mangaSlug: String): SChapter = SChapter.create().apply {
        val chapterStr = if (chapter % 1.0f == 0.0f) chapter.toInt().toString() else chapter.toString()
        name = "Bölüm $chapterStr"
        chapter_number = chapter
        url = "$mangaSlug/$chapterStr"
    }
}

@Serializable
class MangttoPageData(
    val cdn: String = "",
    val uploads: List<MangttoUpload> = emptyList(),
)

@Serializable
class MangttoUpload(
    val fansubId: String? = null,
    val fileLength: Int = 0,
)

